local _, ns = ...
ns.guideText = {
  ["mage"] = "A mage does damage with a cast bar and a mana bar, and the craft is in what to cast and when to stand still. Frost slows and freezes, Fire hits hardest, Arcane saves mana. Every line below presses a button.",
  ["mage-arcane.intro"] = "Arcane runs on mana and on spells that cost nothing. It is slow before 40 and good after, for a mage who would rather cast than flee.",
  ["mage-arcane.note"] = "(31 points in Arcane for Arcane Power, then 20 in Fire).",
  ["mage-arcane.p1"] = "Arcane spells are resisted 10% less.",
  ["mage-arcane.p10"] = "Spells deal 30% more damage and cost 30% more mana for 15 seconds. Every 3 minutes.",
  ["mage-arcane.p11"] = "Fireball casts 0.5 seconds faster.",
  ["mage-arcane.p12"] = "Fire spells have a 10% chance to stun for 2 seconds.",
  ["mage-arcane.p13"] = "A critical Fire hit sets the target burning for 40% more.",
  ["mage-arcane.p14"] = "Fire spells reach 6 yards further.",
  ["mage-arcane.p15"] = "Fire Blast comes back 1.5 seconds sooner.",
  ["mage-arcane.p2"] = "Any damage spell has a 10% chance to make the next one cost nothing.",
  ["mage-arcane.p3"] = "Arcane Missiles is not broken when you are hit.",
  ["mage-arcane.p4"] = "15% of your mana regeneration continues while you cast.",
  ["mage-arcane.p5"] = "Armour equal to half your Intellect. It opens Arcane Mind.",
  ["mage-arcane.p6"] = "Counterspell silences the target for 4 seconds, every time.",
  ["mage-arcane.p7"] = "Your next spell with a cast under 10 seconds becomes instant. Every 3 minutes.",
  ["mage-arcane.p8"] = "10% more mana.",
  ["mage-arcane.p9"] = "3% more spell damage and critical chance.",
  ["mage-arcane.s1.opening"] = "Frost Armor on, Arcane Intellect, Frostbolt from range, step back as it slows, Fire Blast to finish. Wand when mana runs low.",
  ["mage-arcane.s1.r1"] = "Put it on yourself. It adds armour for 30 minutes, so renew it between fights and not in them.",
  ["mage-arcane.s1.r2"] = "Cast it on yourself. 30 minutes of extra Intellect means more mana to spend.",
  ["mage-arcane.s1.r3"] = "Your opener at 35 yards. The cast takes longer with each rank, so you want the monster far away when it starts.",
  ["mage-arcane.s1.r4"] = "Opens at 30 yards and slows the monster by 40% for 5 seconds. It arrives later and you cast again before it does.",
  ["mage-arcane.s1.r5"] = "Press it as the monster arrives or runs. It has no cast bar, so it fills the gap between casts.",
  ["mage-arcane.s1.r6"] = "Hits once a second for 3 seconds, and you cannot move for any of it. Use it only when nothing will reach you while it lasts.",
  ["mage-arcane.s1.r7"] = "A sheep for up to 20 seconds. It works on Beasts, Humanoids and Critters, and any damage wakes it, so leave it alone.",
  ["mage-arcane.s1.r8"] = "Make drinks before you need them. Sitting with one brings mana back and saves a vendor trip.",
  ["mage-arcane.s1.r9"] = "Makes food. Eat between fights to get health back without spending any mana.",
  ["mage-arcane.s2"] = "One monster, levelling. The page is the untalented kit's until the tree helps.",
  ["mage-arcane.s2.r1"] = "Your opener at 30 yards. It slows the monster by 40%.",
  ["mage-arcane.s2.r2"] = "Your hit when the monster is held or you have mana to spare.",
  ["mage-arcane.s2.r3"] = "Hits once a second for 3 seconds. When Arcane Concentration makes your next spell free, cast it, because it costs nothing.",
  ["mage-arcane.s2.r4"] = "Freeze it, step back and keep casting, because a frozen monster cannot hit you.",
  ["mage-arcane.s2.r5"] = "No cast bar, ready every 8 seconds.",
  ["mage-arcane.s2.r6"] = "Hits everything around you at once, so use it when a second monster joins.",
  ["mage-arcane.s2.r7"] = "Turn one into a sheep for up to 20 seconds, so you fight one at a time.",
  ["mage-arcane.s3"] = "One monster, or two, and the first dungeons.",
  ["mage-arcane.s3.opening"] = "Arcane Missiles when it is free, else Frostbolt, Frost Nova if it reaches you.",
  ["mage-arcane.s3.r1"] = "A free cast is the best moment for it. It hits once a second for 4 to 5 seconds.",
  ["mage-arcane.s3.r2"] = "Your slow and your main hit while Arcane Concentration has not made a spell free.",
  ["mage-arcane.s3.r3"] = "Stops that spell and all of the same kind (Fire, Frost) for 10 seconds, and silences for 4 with the talent.",
  ["mage-arcane.s3.r4"] = "8 seconds of standing still for mana. 8 minutes to come back.",
  ["mage-arcane.s3.r5"] = "Absorbs damage by draining mana instead.",
  ["mage-arcane.s3.r6"] = "Moves you 20 yards and frees you from stuns.",
  ["mage-arcane.s3.r7"] = "Your next spell is instant. Use it on the biggest cast you have.",
  ["mage-arcane.s3.r8"] = "Freeze it, step back and keep casting, because a frozen monster cannot hit you.",
  ["mage-arcane.s4"] = "Dungeons, hard monsters and the first raid.",
  ["mage-arcane.s4.opening"] = "Arcane Power on the fight that matters, Presence of Mind on the biggest cast, Arcane Missiles on every free spell.",
  ["mage-arcane.s4.r1"] = "Spells deal 30% more for 15 seconds and cost 30% more mana. Every 3 minutes, so spend it on the one that counts.",
  ["mage-arcane.s4.r2"] = "An instant cast, every 3 minutes. Use it on the biggest cast.",
  ["mage-arcane.s4.r3"] = "Cast it whenever Arcane Concentration makes a spell free, because 5 seconds of damage costs nothing.",
  ["mage-arcane.s4.r4"] = "The cheap hit that slows. Use it between free casts.",
  ["mage-arcane.s4.r5"] = "Hits everything around you at once, so use it when a second monster joins.",
  ["mage-arcane.s4.r6"] = "Stops the spell, and Improved Counterspell silences the monster for 4 seconds.",
  ["mage-arcane.s4.r7"] = "8 seconds of standing still. 8 minutes to come back.",
  ["mage-arcane.s4.r8"] = "Keeps 30% of mana regeneration going while you cast.",
  ["mage-arcane.split"] = "the last 20 points. A second road puts them in Frost (Improved Frostbolt, Frostbite, Permafrost) for a mage who needs the slow. This page takes Fire for the harder hit, and the price is the slow that keeps you alive.",
  ["mage-fire.dry"] = "Combustion held back is a lot of critical hits not dealt.",
  ["mage-fire.intro"] = "Fire hits hardest and sets the monster burning. It has no slow of its own, so the page gives you Frostbolt and Frost Nova for distance.",
  ["mage-fire.note"] = "(31 points in Fire for Combustion, then 20 in Frost).",
  ["mage-fire.p1"] = "Fireball casts 0.5 seconds faster, and it is your main button.",
  ["mage-fire.p10"] = "10% more Fire damage.",
  ["mage-fire.p11"] = "Each Fire hit raises your critical chance by 10% until you have had 3 criticals. Every 3 minutes.",
  ["mage-fire.p12"] = "A Fire or Frost spell is 6% less likely to be resisted.",
  ["mage-fire.p13"] = "Frostbolt casts 0.5 seconds faster, so the slow you rely on comes sooner.",
  ["mage-fire.p14"] = "A chilled monster has a 15% chance to freeze for 5 seconds.",
  ["mage-fire.p15"] = "Frost Nova comes back 4 seconds sooner.",
  ["mage-fire.p16"] = "A chill lasts 3 seconds longer and slows 10% more.",
  ["mage-fire.p17"] = "Finishes the cooldown on all your Frost spells. Every 10 minutes.",
  ["mage-fire.p18"] = "Frost spells cost 15% less mana and draw 30% less threat.",
  ["mage-fire.p2"] = "A critical Fire hit sets the target burning for another 40% of the damage over 4 seconds.",
  ["mage-fire.p3"] = "A big hit with a 6 second cast, and a burn after it. Open with it from 35 yards.",
  ["mage-fire.p4"] = "Fire spells reach 6 yards further, so you open from further away.",
  ["mage-fire.p5"] = "Fire Blast and Scorch are 4% more likely to be critical.",
  ["mage-fire.p6"] = "A critical Fire or Frost spell gives back 30% of its mana.",
  ["mage-fire.p7"] = "A Scorch makes the target take 3% more Fire damage, stacking to 5 times.",
  ["mage-fire.p8"] = "6% more critical chance on Fire spells.",
  ["mage-fire.p9"] = "Damages and dazes all enemies near you, every 45 seconds.",
  ["mage-fire.s1.opening"] = "Frost Armor on, Arcane Intellect, Frostbolt from range, step back as it slows, Fire Blast to finish. Wand when mana runs low.",
  ["mage-fire.s1.r1"] = "Put it on yourself. It adds armour for 30 minutes, so renew it between fights and not in them.",
  ["mage-fire.s1.r2"] = "Cast it on yourself. 30 minutes of extra Intellect means more mana to spend.",
  ["mage-fire.s1.r3"] = "Your opener at 35 yards. The cast takes longer with each rank, so you want the monster far away when it starts.",
  ["mage-fire.s1.r4"] = "Opens at 30 yards and slows the monster by 40% for 5 seconds. It arrives later and you cast again before it does.",
  ["mage-fire.s1.r5"] = "Press it as the monster arrives or runs. It has no cast bar, so it fills the gap between casts.",
  ["mage-fire.s1.r6"] = "Hits once a second for 3 seconds, and you cannot move for any of it. Use it only when nothing will reach you while it lasts.",
  ["mage-fire.s1.r7"] = "A sheep for up to 20 seconds. It works on Beasts, Humanoids and Critters, and any damage wakes it, so leave it alone.",
  ["mage-fire.s1.r8"] = "Make drinks before you need them. Sitting with one brings mana back and saves a vendor trip.",
  ["mage-fire.s1.r9"] = "Makes food. Eat between fights to get health back without spending any mana.",
  ["mage-fire.s2"] = "One monster, levelling.",
  ["mage-fire.s2.opening"] = "Frost Armor, Fireball from 35 yards, Fireball, Frost Nova when it arrives, walk back, cast, Fire Blast.",
  ["mage-fire.s2.r1"] = "Your main button, from 35 yards. A critical one sets the monster burning.",
  ["mage-fire.s2.r2"] = "When you need it slowed. It costs less than Fireball at the same rank, so it is also the cheaper hit.",
  ["mage-fire.s2.r3"] = "Freezes it for up to 8 seconds. Walk back, because damage breaks the freeze and the point is distance.",
  ["mage-fire.s2.r4"] = "Ready every 8 seconds with no cast bar. It finishes a fight, and a critical one starts Ignite.",
  ["mage-fire.s2.r5"] = "Hits everything around you at once, so use it when a second monster joins.",
  ["mage-fire.s2.r6"] = "Turn one into a sheep for up to 20 seconds, so you fight one at a time.",
  ["mage-fire.s3"] = "One monster, or two, and the first dungeons.",
  ["mage-fire.s3.opening"] = "Pyroblast from 35 yards, Fireball, Frost Nova if it reaches you, Fire Blast.",
  ["mage-fire.s3.r1"] = "A 6 second cast and a burn after it. Open with it from 35 yards, because it lands before the monster can reach you.",
  ["mage-fire.s3.r10"] = "8 seconds of standing still for mana. 8 minutes to come back.",
  ["mage-fire.s3.r2"] = "The main button. Its cast time grows with rank, so open with your highest rank and finish with lower ones.",
  ["mage-fire.s3.r3"] = "A 1.5 second cast that costs far less than a Fireball of the same level. Use it to finish a monster when mana is short.",
  ["mage-fire.s3.r4"] = "Instant. Press it when it reaches you or runs.",
  ["mage-fire.s3.r5"] = "Freezes it for up to 8 seconds. Step back and keep casting, because it cannot hit you.",
  ["mage-fire.s3.r6"] = "A 3 second cast on the ground, burning for 8 seconds. It is how you open on a group at range.",
  ["mage-fire.s3.r7"] = "Damages and dazes all near you, every 45 seconds. Use it when a pack arrives.",
  ["mage-fire.s3.r8"] = "Absorbs Fire damage for 30 seconds. Only press it for a monster that casts fire.",
  ["mage-fire.s3.r9"] = "Stops that spell and all of the same kind (Fire, Frost) for 10 seconds.",
  ["mage-fire.s4"] = "Dungeons, hard monsters and the first raid.",
  ["mage-fire.s4.opening"] = "Scorch for the stacks (when the target is worth it), Fireball, Pyroblast, Combustion for the fight that matters.",
  ["mage-fire.s4.r1"] = "The main button. It casts for 3.5 seconds from rank 5, or 3 with Improved Fireball, so start it early.",
  ["mage-fire.s4.r2"] = "Use it early, up to 5 times. Each stack adds Fire damage taken, and it is only worth it if the monster lives long enough.",
  ["mage-fire.s4.r3"] = "A 6 second cast and a burn after it. Open with it.",
  ["mage-fire.s4.r4"] = "Each Fire hit raises your critical chance until you have had 3 criticals. It takes 3 minutes to come back, so choose the fight.",
  ["mage-fire.s4.r5"] = "Instant, every 8 seconds.",
  ["mage-fire.s4.r6"] = "Damages and dazes everything near, every 45 seconds.",
  ["mage-fire.s4.r7"] = "A 3 second cast on the ground and a burn.",
  ["mage-fire.s4.r8"] = "Freeze it, step back and keep casting, because a frozen monster cannot hit you.",
  ["mage-fire.s4.r9"] = "Absorbs Fire damage for 30 seconds.",
  ["mage-fire.split"] = "the last 20 points. A second road puts them in Arcane (Arcane Focus, Arcane Concentration, Arcane Subtlety) for a mage who wants free spells and a bigger mana bar. It gives up the slow and the freeze, which are what keeps a Fire mage alive when the monster arrives. This page takes Frost for that reason.",
  ["mage-frost.intro"] = "Frost keeps the monster slow or frozen so it hits you less, and kills with Frostbolt. It is the mage that survives being alone.",
  ["mage-frost.note"] = "(31 points in Frost for Ice Barrier, then 20 in Arcane).",
  ["mage-frost.p1"] = "Frostbolt casts 0.5 seconds faster, and it is your main button.",
  ["mage-frost.p10"] = "A shield on you that absorbs damage for a minute, and spells are not interrupted while it holds.",
  ["mage-frost.p11"] = "Arcane spells are resisted 10% less. Mostly the way to the next row.",
  ["mage-frost.p12"] = "The target resists your spells less, and Arcane spells draw 40% less threat.",
  ["mage-frost.p13"] = "Any damage spell has a 10% chance to make the next one cost nothing.",
  ["mage-frost.p14"] = "25% more damage with a wand, and a wand costs no mana.",
  ["mage-frost.p15"] = "All resistances up 10, and a fully resisted spell gives back 5% of your mana.",
  ["mage-frost.p16"] = "Armour equal to half your Intellect. The last point. Any talent you can reach would do as well.",
  ["mage-frost.p2"] = "A Frost or Fire spell is 6% less likely to be resisted.",
  ["mage-frost.p3"] = "A chilled monster has a 15% chance to freeze for 5 seconds at 3/3.",
  ["mage-frost.p4"] = "6% more Frost damage.",
  ["mage-frost.p5"] = "Frost Nova comes back 4 seconds sooner, and it opens Shatter.",
  ["mage-frost.p6"] = "Spells are 50% more likely to be critical against a frozen monster.",
  ["mage-frost.p7"] = "You are safe from everything for 10 seconds, but cannot do anything, and it takes 5 minutes to come back. It opens Ice Barrier.",
  ["mage-frost.p8"] = "Cone of Cold hits 35% harder.",
  ["mage-frost.p9"] = "Each Frost hit raises the chance of a Frost critical on that target by 2%, up to 5 times.",
  ["mage-frost.s1.opening"] = "Frost Armor on, Arcane Intellect, Frostbolt from range, step back as it slows, Fire Blast to finish. Wand when mana runs low.",
  ["mage-frost.s1.r1"] = "Put it on yourself. It adds armour for 30 minutes, so renew it between fights and not in them.",
  ["mage-frost.s1.r2"] = "Cast it on yourself. 30 minutes of extra Intellect means more mana to spend.",
  ["mage-frost.s1.r3"] = "Your opener at 35 yards. The cast takes longer with each rank, so you want the monster far away when it starts.",
  ["mage-frost.s1.r4"] = "Opens at 30 yards and slows the monster by 40% for 5 seconds. It arrives later and you cast again before it does.",
  ["mage-frost.s1.r5"] = "Press it as the monster arrives or runs. It has no cast bar, so it fills the gap between casts.",
  ["mage-frost.s1.r6"] = "Hits once a second for 3 seconds, and you cannot move for any of it. Use it only when nothing will reach you while it lasts.",
  ["mage-frost.s1.r7"] = "A sheep for up to 20 seconds. It works on Beasts, Humanoids and Critters, and any damage wakes it, so leave it alone.",
  ["mage-frost.s1.r8"] = "Make drinks before you need them. Sitting with one brings mana back and saves a vendor trip.",
  ["mage-frost.s1.r9"] = "Makes food. Eat between fights to get health back without spending any mana.",
  ["mage-frost.s2"] = "One monster, levelling.",
  ["mage-frost.s2.opening"] = "Frost Armor on, Frostbolt from 30 yards, Frostbolt again, Frost Nova when it arrives, walk back and cast, Fire Blast or wand to finish.",
  ["mage-frost.s2.r1"] = "Your main button, and it slows the monster by 40%. Cast it from as far as 30 yards.",
  ["mage-frost.s2.r2"] = "Freezes everything near you for up to 8 seconds. Walk back, because damage breaks the freeze and the point is distance.",
  ["mage-frost.s2.r3"] = "No cast bar, ready every 8 seconds. It finishes a fight a Frostbolt would not.",
  ["mage-frost.s2.r4"] = "Hits everything around you at once. It is your answer when a second monster joins.",
  ["mage-frost.s2.r5"] = "Turn one into a sheep for up to 20 seconds and deal with the other first.",
  ["mage-frost.s2.r6"] = "Renew it when it ends.",
  ["mage-frost.s3"] = "One monster, or two, and the first dungeons.",
  ["mage-frost.s3.opening"] = "Frostbolt, Frostbolt, Frost Nova if it reaches you, Fire Blast. Ice Armor from 30.",
  ["mage-frost.s3.r1"] = "Still your main button. Its cast reaches 3 seconds at rank 5, so start it while the monster is far.",
  ["mage-frost.s3.r10"] = "Safe from everything for 10 seconds, but you cannot act, and it takes 5 minutes to come back.",
  ["mage-frost.s3.r2"] = "Freeze, step back, cast. It comes back in 25 seconds, or 21 with Improved Frost Nova.",
  ["mage-frost.s3.r3"] = "Hits everything in front of you and slows it 50% for 8 seconds, ready every 10.",
  ["mage-frost.s3.r4"] = "Stand still and it rains ice for 8 seconds on the ground you chose. Pull a pack into it.",
  ["mage-frost.s3.r5"] = "Stops a spell and its whole school for 10 seconds. It takes 30 seconds to come back.",
  ["mage-frost.s3.r6"] = "Moves you 20 yards and frees you from stuns and roots. It takes 15 seconds to come back.",
  ["mage-frost.s3.r7"] = "8 seconds of standing still that brings back mana much faster. It takes 8 minutes to come back, so use it once per long outing.",
  ["mage-frost.s3.r8"] = "Replaces Frost Armor, with more armour and a slow on melee attackers.",
  ["mage-frost.s3.r9"] = "Absorbs damage by draining mana instead. Press it when you would die before you ran dry.",
  ["mage-frost.s4"] = "Dungeons, hard monsters and the first raid.",
  ["mage-frost.s4.opening"] = "Ice Barrier, Frostbolt from 30 yards, Frost Nova, Cone of Cold.",
  ["mage-frost.s4.r1"] = "A shield on you that absorbs damage, and spells are not interrupted while it holds. It takes 30 seconds to come back.",
  ["mage-frost.s4.r2"] = "Your main button. Each hit adds a Winter's Chill stack, up to 5, and each stack raises your Frost critical chance on that monster by 2%.",
  ["mage-frost.s4.r3"] = "Freeze, step back, cast. Shatter raises your critical chance against a frozen monster by 50%.",
  ["mage-frost.s4.r4"] = "Hits harder with Improved Cone of Cold and slows 50% for 8 seconds.",
  ["mage-frost.s4.r5"] = "8 seconds of ice on the ground. Use it with a Frost Nova between you and them.",
  ["mage-frost.s4.r6"] = "Stops the school for 10 seconds, ready every 30.",
  ["mage-frost.s4.r7"] = "Keeps 30% of mana regeneration going while you cast. Use it when mana, not health, runs out first.",
  ["mage-frost.s4.r8"] = "Safe for 10 seconds, but you cannot act, and it takes 5 minutes to come back.",
  ["mage-frost.s4.r9"] = "8 seconds of standing still for a lot of mana back. 8 minutes to come back.",
  ["mage-frost.split"] = "the last 20 points. A second road puts them in Fire (Improved Fireball, Impact, Ignite) for a mage who wants a harder hit. It gives you a bigger opening and gives up the free spells and the spell resistance. This page takes Arcane for the mana.",
  ["mage.advice.damage"] = "Frost. The safest way to level alone. A frozen or slowed monster hits you less. The price: Frost hits a little softer than Fire. Fire. The hardest hit. Fire has no slow, so Frostbolt and Frost Nova stay on the bar. The price: a monster that reaches you stays on you. Arcane. Mana and free spells. The price: most of the tree's damage arrives with Arcane Power at 40, so before then you level slower than the other two.",
  ["paladin"] = "A paladin keeps one seal, one aura and one blessing on each friend, and every one of them lasts a set time (a seal 30 seconds, a blessing 5 minutes). Mana runs the class. Retribution fights with a seal and Judgement, Holy heals, Protection holds. Every line below presses a button.",
  ["paladin-holy.intro"] = "Holy keeps people alive. The page cannot give a fixed order, because a healer's job is to answer whoever is losing health. It gives what each button is for, and when.",
  ["paladin-holy.note"] = "(31 points in Holy for Holy Shock, then 20 in Protection).",
  ["paladin-holy.p1"] = "10% more Intellect, so more mana and more heals.",
  ["paladin-holy.p10"] = "An instant heal on a friend, or damage on an enemy, every 30 seconds.",
  ["paladin-holy.p11"] = "Devotion Aura gives 25% more armour to the group.",
  ["paladin-holy.p12"] = "10% more armour from your gear.",
  ["paladin-holy.p13"] = "10 more Defense skill, so fewer hits land.",
  ["paladin-holy.p14"] = "The aura adds 15% to its effect, and the group resists silence and interrupt 15% more.",
  ["paladin-holy.p15"] = "Blessing of Protection comes back 2 minutes sooner.",
  ["paladin-holy.p2"] = "A heal keeps casting when you are hit (70% of the time), so you can heal mid-pull.",
  ["paladin-holy.p3"] = "12% more from Holy Light and Flash of Light.",
  ["paladin-holy.p4"] = "The cooldown drops from 1 hour to 40 minutes, and the target gets 30% more armour for 2 minutes. It opens the row for Illumination.",
  ["paladin-holy.p5"] = "After a critical heal you get back the mana the spell cost.",
  ["paladin-holy.p6"] = "Your next heal is a guaranteed critical, every 2 minutes. Use it on the big heal.",
  ["paladin-holy.p7"] = "Blessing of Wisdom is 20% stronger.",
  ["paladin-holy.p8"] = "10% more chance to resist fear and disorient. You take it to reach the next row.",
  ["paladin-holy.p9"] = "5% more critical chance on Holy spells.",
  ["paladin-holy.s1.opening"] = "Devotion Aura on, Blessing of Might, Seal of Righteousness, then hit. Judgement when it is ready, the seal again after it, Holy Light once the fight is over.",
  ["paladin-holy.s1.r1"] = "Put it on first. You and your party within 30 yards take less damage from every hit, until you change it.",
  ["paladin-holy.s1.r2"] = "Press it at the start of every pull. It lasts 30 seconds and adds Holy damage to each swing, and a slower weapon gets more out of it.",
  ["paladin-holy.s1.r3"] = "Whenever it is ready, every 10 seconds. It sets off the seal you wear, so put the seal back on after it.",
  ["paladin-holy.s1.r4"] = "Before the first pull and again when it ends. It adds attack power for 5 minutes, so it pays back over many fights.",
  ["paladin-holy.s1.r5"] = "Heal when nothing is hitting you. The cast takes 2.5 seconds and a hit can ruin it, so it belongs after the pull.",
  ["paladin-holy.s1.r6"] = "You swing 40% faster but each hit is weaker. Stay on Seal of Righteousness with a slow weapon, since the slower the weapon the more it adds.",
  ["paladin-holy.s1.r7"] = "You take nothing for 6 seconds but cannot attack, and it takes 5 minutes to come back. Keep it for the fight that would otherwise kill you.",
  ["paladin-holy.s1.r8"] = "A 3 second stun on a 1 minute cooldown. Press it to stop a monster running, or to buy the 2.5 seconds a Holy Light needs.",
  ["paladin-holy.s1.r9"] = "Removes 1 disease and 1 poison. Press it when a monster's sting is the thing wearing you down.",
  ["paladin-holy.s2"] = "A group, or one hurt friend. The page is a list of what each button is for.",
  ["paladin-holy.s2.r1"] = "The big heal. The cast takes 2.5 seconds, so use it only when the target will live that long.",
  ["paladin-holy.s2.r2"] = "On yourself and on the other casters. It gives 10 mana every 5 seconds for 5 minutes.",
  ["paladin-holy.s2.r3"] = "Keep it on. The group within 30 yards gets more armour, and it lasts until you change it.",
  ["paladin-holy.s2.r4"] = "6 seconds in which no physical attack reaches them, but they cannot fight either. 5 minutes to come back.",
  ["paladin-holy.s2.r5"] = "Removes one of each. Press it when it is the thing hurting someone.",
  ["paladin-holy.s2.r6"] = "Heals them for your full health and empties your mana. It takes 1 hour to come back, so save it for the moment.",
  ["paladin-holy.s3"] = "Dungeons.",
  ["paladin-holy.s3.r1"] = "A 1.5 second heal at a fraction of Holy Light's mana. Use it for most healing, and save Holy Light for the big hits.",
  ["paladin-holy.s3.r2"] = "The 2.5 second cast. Save it for the moment the tank is nearly gone, because the cast is long.",
  ["paladin-holy.s3.r3"] = "Your next heal is a critical. Use it on a Holy Light for the biggest heal you will get.",
  ["paladin-holy.s3.r4"] = "35% chance to ignore interrupts, for all in 30 yards. Swap Devotion Aura for it when casters get hit.",
  ["paladin-holy.s3.r5"] = "Your swing may return 50 mana, but a healer who swings is not healing. Use it only when standing idle.",
  ["paladin-holy.s3.r6"] = "On the casters, because mana is what runs out.",
  ["paladin-holy.s3.r7"] = "10 seconds with no slowing or rooting. The cooldown is 20 seconds, so use it when someone is stuck.",
  ["paladin-holy.s3.r8"] = "Brings them back with a little health and mana. Cannot be cast in combat.",
  ["paladin-holy.s4"] = "Dungeons and raids.",
  ["paladin-holy.s4.r1"] = "An instant heal on a 30 second cooldown. Use it when a hole is too sudden for a cast.",
  ["paladin-holy.s4.r2"] = "The main heal, because it costs little and casts in 1.5 seconds.",
  ["paladin-holy.s4.r3"] = "For the tank's worst moments. Cast Divine Favor first, so this heal is a critical.",
  ["paladin-holy.s4.r4"] = "Removes one of each. Use it before the next heal if the effect is the damage.",
  ["paladin-holy.s4.r5"] = "One blessing for every healer or caster of a class in the group. It saves buffing each player one by one.",
  ["paladin-holy.s4.r6"] = "Gives a friend 3 minutes of nothing hurting them, and it costs you your life. It takes 1 hour.",
  ["paladin-holy.split"] = "the last 20 points. A second road puts them in Retribution (Benediction, Improved Judgement, Conviction) for a healer who also fights alone. Your seals cost less and Judgement comes back sooner, and you give up the aura and the armour. This page takes Protection for the group.",
  ["paladin-protection.dry"] = "A monster still on you after 20 seconds means the job is working.",
  ["paladin-protection.intro"] = "Protection holds monsters on you and stays up. Threat is the list a monster keeps of who to hit next. The book has no taunt, so Righteous Fury, your seal and Holy Shield are what keep a monster looking at you.",
  ["paladin-protection.note"] = "(31 points in Protection for Holy Shield, then 20 in Holy).",
  ["paladin-protection.p1"] = "After a critical hit on you, 30% more block for 10 seconds or 5 blocks. It also opens Shield Specialization.",
  ["paladin-protection.p10"] = "10% more Intellect, which is mana for the next pull.",
  ["paladin-protection.p11"] = "15% more damage from Seal of Righteousness and its Judgement, which is threat.",
  ["paladin-protection.p12"] = "Holy damage on the ground around you for 8 seconds. This is your first area threat.",
  ["paladin-protection.p13"] = "12% more from Holy Light and Flash of Light.",
  ["paladin-protection.p14"] = "A heal keeps casting when you are hit (70% of the time), so you can heal mid-pull.",
  ["paladin-protection.p15"] = "The last point. Any talent you can reach would do as well.",
  ["paladin-protection.p2"] = "10% more armour from your gear.",
  ["paladin-protection.p3"] = "Righteous Fury gives 50% more threat, which is your whole job.",
  ["paladin-protection.p4"] = "10 more Defense skill, so fewer hits land and fewer are critical.",
  ["paladin-protection.p5"] = "3% more chance to hit, so Judgement and your seals land more.",
  ["paladin-protection.p6"] = "Less damage from every hit taken, and a block hurts the attacker. It opens Holy Shield.",
  ["paladin-protection.p7"] = "Your shield absorbs 30% more.",
  ["paladin-protection.p8"] = "10% more damage with a one-hander, which is threat.",
  ["paladin-protection.p9"] = "30% more block for 10 seconds and Holy damage for every block.",
  ["paladin-protection.s1.opening"] = "Devotion Aura on, Blessing of Might, Seal of Righteousness, then hit. Judgement when it is ready, the seal again after it, Holy Light once the fight is over.",
  ["paladin-protection.s1.r1"] = "Put it on first. You and your party within 30 yards take less damage from every hit, until you change it.",
  ["paladin-protection.s1.r2"] = "Press it at the start of every pull. It lasts 30 seconds and adds Holy damage to each swing, and a slower weapon gets more out of it.",
  ["paladin-protection.s1.r3"] = "Whenever it is ready, every 10 seconds. It sets off the seal you wear, so put the seal back on after it.",
  ["paladin-protection.s1.r4"] = "Before the first pull and again when it ends. It adds attack power for 5 minutes, so it pays back over many fights.",
  ["paladin-protection.s1.r5"] = "Heal when nothing is hitting you. The cast takes 2.5 seconds and a hit can ruin it, so it belongs after the pull.",
  ["paladin-protection.s1.r6"] = "You swing 40% faster but each hit is weaker. Stay on Seal of Righteousness with a slow weapon, since the slower the weapon the more it adds.",
  ["paladin-protection.s1.r7"] = "You take nothing for 6 seconds but cannot attack, and it takes 5 minutes to come back. Keep it for the fight that would otherwise kill you.",
  ["paladin-protection.s1.r8"] = "A 3 second stun on a 1 minute cooldown. Press it to stop a monster running, or to buy the 2.5 seconds a Holy Light needs.",
  ["paladin-protection.s1.r9"] = "Removes 1 disease and 1 poison. Press it when a monster's sting is the thing wearing you down.",
  ["paladin-protection.s2"] = "A shield, a group. The tree opens at 10.",
  ["paladin-protection.s2.opening"] = "Devotion Aura, Righteous Fury (from 16), Seal of Righteousness, then hit.",
  ["paladin-protection.s2.r1"] = "Turn it on. Your Holy attacks draw 60% more attention, and it lasts 30 minutes, so once an outing is enough.",
  ["paladin-protection.s2.r2"] = "On before the first hit. It adds Holy damage to each swing, and Righteous Fury makes that damage count as threat.",
  ["paladin-protection.s2.r3"] = "Every 10 seconds, because it is damage and so threat.",
  ["paladin-protection.s2.r4"] = "The group within 30 yards takes less from each hit.",
  ["paladin-protection.s2.r5"] = "A 3 second stun. Use it on the one that went for the healer.",
  ["paladin-protection.s2.r6"] = "Heal when nothing is hitting you, because the cast takes 2.5 seconds.",
  ["paladin-protection.s3"] = "Dungeons, groups of monsters.",
  ["paladin-protection.s3.r1"] = "On before the pull. Your Holy attacks draw 60% more attention.",
  ["paladin-protection.s3.r2"] = "Your seal. Seal of Command is not yours until you take the Retribution road.",
  ["paladin-protection.s3.r3"] = "Every 10 seconds on the monster you are holding, because it is damage and so threat.",
  ["paladin-protection.s3.r4"] = "Stuns it for 4 seconds at rank 2. 1 minute to come back.",
  ["paladin-protection.s3.r5"] = "On yourself before the pull. Less damage from each hit, and a blocked attacker takes Holy damage.",
  ["paladin-protection.s3.r6"] = "Pulls the damage off them for 8 seconds at rank 2, but they cannot fight. 5 minutes to come back.",
  ["paladin-protection.s3.r7"] = "The group is less likely to be interrupted while hit.",
  ["paladin-protection.s3.r8"] = "8 seconds with nothing hurting you, but you cannot attack. 5 minutes to come back.",
  ["paladin-protection.s4"] = "Dungeons and raids.",
  ["paladin-protection.s4.opening"] = "Righteous Fury, Holy Shield, Seal of Righteousness, Judgement. The first move on a pack is Consecration, from 51.",
  ["paladin-protection.s4.r1"] = "Keep it up. It lasts 10 seconds and returns in 10, so it can cover the whole fight, adding block, Holy damage per block and 20% more threat.",
  ["paladin-protection.s4.r2"] = "Keep it on. It is the damage that Righteous Fury makes threat.",
  ["paladin-protection.s4.r3"] = "Every 10 seconds, because it is damage and so threat.",
  ["paladin-protection.s4.r4"] = "8 seconds of Holy damage around you. Stand where the pack stands.",
  ["paladin-protection.s4.r5"] = "5 seconds of stun on a 1 minute cooldown. Use it on the one that is the problem.",
  ["paladin-protection.s4.r6"] = "Keep it on yourself, because every hit taken is a little smaller.",
  ["paladin-protection.s4.r7"] = "10 seconds with nothing hurting you, but your attacks come half as often. 5 minutes to come back.",
  ["paladin-protection.split"] = "the last 20 points. A second road puts them in Retribution (Benediction, Deflection, Conviction, Improved Judgement, Vindication) for more parry and more critical hits. This page takes Holy because Consecration is the only way a paladin holds a pack, and the price is parry and critical chance.",
  ["paladin-retribution.dry"] = "Most of this page waits on Judgement. If it is not ready, hit the monster.",
  ["paladin-retribution.intro"] = "Retribution fights in melee with one big weapon and a seal that adds to every swing. It is the paladin that kills alone. The rest of the page is about which seal, and when to spend it with Judgement.",
  ["paladin-retribution.note"] = "(31 points in Retribution for Repentance, then 20 in Holy).",
  ["paladin-retribution.p1"] = "Judgement and your seals cost 15% less mana, and they are what you press most.",
  ["paladin-retribution.p10"] = "After a critical hit you deal 15% more physical and Holy damage for 8 seconds.",
  ["paladin-retribution.p11"] = "Puts a humanoid out of the fight for up to 6 seconds, until you or someone else hurts it.",
  ["paladin-retribution.p12"] = "10% more Strength, which is attack power.",
  ["paladin-retribution.p13"] = "10% more Intellect, which is mana.",
  ["paladin-retribution.p14"] = "A heal keeps casting when you are hit (70% of the time), which you need to heal mid-pull.",
  ["paladin-retribution.p15"] = "Holy damage on the ground around you for 8 seconds. It is how a damage paladin handles a pack.",
  ["paladin-retribution.p16"] = "12% more from Holy Light and Flash of Light, so you heal between pulls faster.",
  ["paladin-retribution.p17"] = "The last point. Any talent you can reach would do as well.",
  ["paladin-retribution.p2"] = "Judgement is ready 2 seconds sooner, so a seal pays out more often.",
  ["paladin-retribution.p3"] = "3% more parry. The 10th point in the tree opens the row that holds Seal of Command.",
  ["paladin-retribution.p4"] = "A seal that sometimes adds Holy damage worth 70% of a normal hit. Its Judgement hits harder on a stunned monster.",
  ["paladin-retribution.p5"] = "5% more critical chance with melee weapons. It opens Vengeance later.",
  ["paladin-retribution.p6"] = "The last two ranks, for 5% more parry in all.",
  ["paladin-retribution.p7"] = "8% faster on foot and on a mount, and you travel at every level.",
  ["paladin-retribution.p8"] = "6% more damage with a two-hander. This is the reason for the weapon.",
  ["paladin-retribution.p9"] = "Nothing here helps you much. It is the cheapest way to the next row.",
  ["paladin-retribution.s1.opening"] = "Devotion Aura on, Blessing of Might, Seal of Righteousness, then hit. Judgement when it is ready, the seal again after it, Holy Light once the fight is over.",
  ["paladin-retribution.s1.r1"] = "Put it on first. You and your party within 30 yards take less damage from every hit, until you change it.",
  ["paladin-retribution.s1.r2"] = "Press it at the start of every pull. It lasts 30 seconds and adds Holy damage to each swing, and a slower weapon gets more out of it.",
  ["paladin-retribution.s1.r3"] = "Whenever it is ready, every 10 seconds. It sets off the seal you wear, so put the seal back on after it.",
  ["paladin-retribution.s1.r4"] = "Before the first pull and again when it ends. It adds attack power for 5 minutes, so it pays back over many fights.",
  ["paladin-retribution.s1.r5"] = "Heal when nothing is hitting you. The cast takes 2.5 seconds and a hit can ruin it, so it belongs after the pull.",
  ["paladin-retribution.s1.r6"] = "You swing 40% faster but each hit is weaker. Stay on Seal of Righteousness with a slow weapon, since the slower the weapon the more it adds.",
  ["paladin-retribution.s1.r7"] = "You take nothing for 6 seconds but cannot attack, and it takes 5 minutes to come back. Keep it for the fight that would otherwise kill you.",
  ["paladin-retribution.s1.r8"] = "A 3 second stun on a 1 minute cooldown. Press it to stop a monster running, or to buy the 2.5 seconds a Holy Light needs.",
  ["paladin-retribution.s1.r9"] = "Removes 1 disease and 1 poison. Press it when a monster's sting is the thing wearing you down.",
  ["paladin-retribution.s2"] = "One monster, levelling. Few points are spent yet, so the untalented kit's advice still holds.",
  ["paladin-retribution.s2.opening"] = "Blessing of Might, Seal of Righteousness, hit, Judgement when it is ready.",
  ["paladin-retribution.s2.r1"] = "Press it at the start of every pull, because it lasts 30 seconds and adds to every swing.",
  ["paladin-retribution.s2.r2"] = "Every 10 seconds, or 8 with Improved Judgement. It sets off the seal, so put the seal back on after.",
  ["paladin-retribution.s2.r3"] = "Keep it up. It adds attack power for 5 minutes.",
  ["paladin-retribution.s2.r4"] = "Swap Might for it when you run out of mana before monsters. It gives 10 mana every 5 seconds for 5 minutes.",
  ["paladin-retribution.s2.r5"] = "Leave it off. It makes your Holy attacks draw 60% more attention, and in a group you want the tank to have it.",
  ["paladin-retribution.s2.r6"] = "Heal when nothing is hitting you, because the cast takes 2.5 seconds.",
  ["paladin-retribution.s2.r7"] = "A 3 second stun. It stops a runner and gives a Holy Light time to land.",
  ["paladin-retribution.s2.r8"] = "Heals you for your full health and empties your mana. It takes 1 hour to come back.",
  ["paladin-retribution.s3"] = "One monster, or two, and the first dungeons.",
  ["paladin-retribution.s3.opening"] = "Blessing of Might, Seal of Command, hit, Judgement. Exorcism first on anything undead.",
  ["paladin-retribution.s3.r1"] = "Your seal from 20. Each swing may add Holy damage worth 70% of a normal hit.",
  ["paladin-retribution.s3.r10"] = "Nothing hurts you for 10 seconds, but your attacks come half as often. It shares a 5 minute wait with Divine Protection. Using either, or Blessing of Protection, blocks all three for 1 minute.",
  ["paladin-retribution.s3.r2"] = "Every 10 seconds, as before. With Seal of Command it is a bigger hit.",
  ["paladin-retribution.s3.r3"] = "Stun, then Judgement. Judgement of Command hits harder on a stunned monster, and Hammer of Justice stuns for 4 seconds at rank 2.",
  ["paladin-retribution.s3.r4"] = "An instant Holy hit on a 15 second cooldown that works only on undead and demons. Use it every time one is in front of you.",
  ["paladin-retribution.s3.r5"] = "A 1.5 second heal that costs far less than Holy Light. Use it when you are missing only a little.",
  ["paladin-retribution.s3.r6"] = "The seal gives swings a chance to stun for 2 seconds, and its Judgement stops the monster fleeing for 10. Swap to it only for a runner.",
  ["paladin-retribution.s3.r7"] = "Swap Might for it when mana is the limit. 15 mana every 5 seconds at rank 2.",
  ["paladin-retribution.s3.r8"] = "8 seconds of nothing hurting you at rank 2, but you cannot attack. It comes back in 5 minutes.",
  ["paladin-retribution.s3.r9"] = "Each swing may heal you, so it buys time in a fight you are losing slowly. It does less damage than Seal of Command.",
  ["paladin-retribution.s4"] = "Dungeons, hard monsters and the first raid.",
  ["paladin-retribution.s4.opening"] = "Blessing of Might (or its group version at 52), Seal of Command, hit, Judgement. Repentance on a humanoid that heals.",
  ["paladin-retribution.s4.r1"] = "Keep it on, because it is your main damage between Judgements.",
  ["paladin-retribution.s4.r2"] = "Every 10 seconds. The seal is gone after it, so press it again.",
  ["paladin-retribution.s4.r3"] = "Hurls a hammer from 30 yards on a 6 second cooldown, but only at a monster nearly dead. Press it before melee ends the fight.",
  ["paladin-retribution.s4.r4"] = "Every 15 seconds. It works on nothing else.",
  ["paladin-retribution.s4.r5"] = "Up to 6 seconds out of the fight, until it is hurt. It takes 1 minute to come back. Use it on a humanoid that heals itself.",
  ["paladin-retribution.s4.r6"] = "Holy damage on the ground for 8 seconds. Stand in it with the pack and it does the work between Judgements.",
  ["paladin-retribution.s4.r7"] = "One blessing for everyone of a class in the group, 15 minutes. It saves buffing each player one by one.",
  ["paladin-retribution.s4.r8"] = "Removes one of each. Press it when the fight is being lost to something on you.",
  ["paladin-retribution.s4.r9"] = "10 seconds of no damage, 12 at rank 2. It comes back in 5 minutes.",
  ["paladin-retribution.split"] = "the last 20 points. A second road puts them in Protection (Precision, Toughness, Anticipation) for a paladin who wants more hit and more armour in dungeons, and gives up the extra Strength and mana. This page takes Holy, because both stats are in every fight and a solo paladin is always short of mana.",
  ["paladin.advice.damage"] = "Take it if you level alone. A damage paladin works with a seal and Judgement and heals between pulls with Holy Light, so it needs no group. The price: no taunt and no way to heal in a fight, so in a dungeon you will want a tank and a healer beside you.",
  ["paladin.advice.heal"] = "Take it if you will mostly play in a group, because a paladin who heals is always wanted there. The price: a Holy paladin kills slowly alone, so levelling takes longer.",
  ["paladin.advice.tank"] = "Take it if you will hold monsters for a group. The price: the book has no taunt, so a monster that goes for someone else stays on them until you hit it again. Protection also levels slowly alone and has no threat on a pack until Consecration, which this path takes at 51.",
  ["warrior"] = "Stances change what you can press. Battle Stance is yours at level 1, Defensive Stance at 10 and Berserker Stance at 30, both from quests. Rage comes from hitting and from being hit, and it drains when you stop. Every line below presses a button.",
  ["warrior-arms.dry"] = "Rage spent on Heroic Strike is rage Mortal Strike will not have when it comes off its cooldown.",
  ["warrior-arms.intro"] = "Arms hits slowly and hard with one big weapon. If you carry a two-hander, this is your tree. The rest of the page is about spending the rage you did not use.",
  ["warrior-arms.note"] = "(31 points in Arms for Mortal Strike, then 20 in Fury).",
  ["warrior-arms.p1"] = "Heroic Strike is the button you press most while levelling. Each rank makes it cheaper in rage.",
  ["warrior-arms.p10"] = "Pick the one that matches your weapon. Axe and Polearm add critical chance, Mace may stun, Sword may give an extra attack. Say what you wield and the page follows.",
  ["warrior-arms.p11"] = "The hardest hit you have, and it halves the healing on its target.",
  ["warrior-arms.p12"] = "1% critical chance per rank.",
  ["warrior-arms.p13"] = "Each hit can give you an extra point of rage, which keeps the next ability coming.",
  ["warrior-arms.p14"] = "5% more of the attack power Battle Shout gives, per rank, to you and the group.",
  ["warrior-arms.p15"] = "After you are critically hit, your damage rises for a few swings.",
  ["warrior-arms.p2"] = "Your bleed does 15% more at rank 1 and 35% more at 3/3, and Deep Wounds needs it later.",
  ["warrior-arms.p3"] = "You keep some of your rage when you change stance. Without it, every change empties you.",
  ["warrior-arms.p4"] = "Overpower is the hit you get for a dodge, and this makes it critical more often.",
  ["warrior-arms.p5"] = "Rage drains more slowly while you are out of a fight, so the next pull starts with some.",
  ["warrior-arms.p6"] = "Your criticals leave a bleed. It needs Improved Rend maxed.",
  ["warrior-arms.p7"] = "1% more damage per rank with two hands. This is the reason for the weapon.",
  ["warrior-arms.p8"] = "Your critical hits do more damage. Needs Deep Wounds maxed.",
  ["warrior-arms.p9"] = "The next hits strike a second enemy nearby. Mortal Strike needs it.",
  ["warrior-arms.s1"] = "One monster, levelling. Battle Stance only until 10.",
  ["warrior-arms.s1.opening"] = "Charge from range (4), Rend (4), then Heroic Strike with whatever rage you have.",
  ["warrior-arms.s1.r1"] = "Start every pull with it. It stuns the monster and hands you rage for the first hit.",
  ["warrior-arms.s1.r2"] = "On a monster that will live long enough to pay it back. It keeps hurting while you hit.",
  ["warrior-arms.s1.r3"] = "Spend spare rage here. It lands on your next swing, and rage you keep only drains.",
  ["warrior-arms.s1.r4"] = "Slows their attacks and hits them all. Skip it on a single weak monster.",
  ["warrior-arms.s1.r5"] = "When a monster runs, so you can keep hitting it. Its slow is half speed.",
  ["warrior-arms.s1.r6"] = "Press it at the start of a pull while your health is full. It pays rage for health.",
  ["warrior-arms.s1.r7"] = "The hit you get for a dodge. The monster cannot block, dodge or parry it, so press it when the dodge shows.",
  ["warrior-arms.s2"] = "One monster or two, levelling and the first dungeons.",
  ["warrior-arms.s2.opening"] = "Battle Shout, Charge, Rend if it will live, then your best free hit.",
  ["warrior-arms.s2.r1"] = "Before the pull. More attack power for you and the group, and it is one button.",
  ["warrior-arms.s2.r2"] = "Still the best first move, because it hands you rage before the first swing.",
  ["warrior-arms.s2.r3"] = "Hits the monster and the one beside it. Use it instead of Heroic Strike when two are on you.",
  ["warrior-arms.s2.r4"] = "Everything else waits, because Execute turns every spare point of rage into damage.",
  ["warrior-arms.s2.r5"] = "The hit you get for a dodge, and it cannot be blocked, dodged or parried.",
  ["warrior-arms.s2.r6"] = "It is a hit with weapon damage plus a bit more. Use it when rage is high and nothing better is ready, because it slows your next swing.",
  ["warrior-arms.s2.r7"] = "Worth it only if you keep rage across the change. Otherwise stay in Battle Stance.",
  ["warrior-arms.s2.r8"] = "One hit on up to 4 enemies. It is your best button on a group, and on one monster it is still cheap damage.",
  ["warrior-arms.s2.r9"] = "Your next hits strike a second enemy nearby. Press it before a pull of two or more.",
  ["warrior-arms.s3"] = "Dungeons, hard monsters and the first raid.",
  ["warrior-arms.s3.opening"] = "Battle Shout, Charge, Mortal Strike, then Whirlwind or Overpower as the game offers them.",
  ["warrior-arms.s3.r1"] = "Renew it when it ends, because the bonus goes with it.",
  ["warrior-arms.s3.r2"] = "The opening, because it stuns the monster and gives you rage.",
  ["warrior-arms.s3.r3"] = "On its cooldown. It is your hardest hit, and it halves the healing on its target.",
  ["warrior-arms.s3.r4"] = "Press it between Mortal Strikes, because it is cheap damage while you wait.",
  ["warrior-arms.s3.r5"] = "A hit that cannot be blocked, dodged or parried. Press it before the window closes.",
  ["warrior-arms.s3.r6"] = "Put everything else down. Spend all your rage on it.",
  ["warrior-arms.s3.r7"] = "Last, and only with rage you would otherwise waste, because it takes rage from your better buttons.",
  ["warrior-arms.s3.r8"] = "Early in a long fight, because it pays back over time.",
  ["warrior-arms.s3.r9"] = "Before the pull. Then Whirlwind, for groups.",
  ["warrior-arms.split"] = "the last 20 points. A second road puts them into Deflection and the other Arms rows, for a warrior who cares more about surviving a solo grind than about damage. The damage road is the one on this page. The other buys some parry and gives up critical chance and a bigger shout.",
  ["warrior-fury.intro"] = "Fury is the warrior who hits often with two weapons and lives on the rage that comes from being hit and from critical strikes. It rewards wearing two real weapons, and a pull that keeps going.",
  ["warrior-fury.note"] = "(31 points in Fury for Bloodthirst, then 20 in Arms).",
  ["warrior-fury.p1"] = "1% critical chance per rank. Critical hits feed the rest of the tree.",
  ["warrior-fury.p10"] = "A stronger bleed, and the row Deep Wounds needs.",
  ["warrior-fury.p11"] = "You keep some of your rage when you change stance.",
  ["warrior-fury.p12"] = "The point that Bloodthirst's gate had no room for.",
  ["warrior-fury.p13"] = "Your free hit lands critically more often.",
  ["warrior-fury.p14"] = "Rage drains more slowly out of a fight.",
  ["warrior-fury.p15"] = "Your criticals leave a bleed.",
  ["warrior-fury.p16"] = "Your critical hits do more.",
  ["warrior-fury.p2"] = "Each hit may give an extra point of rage. The cheapest rage you will ever get.",
  ["warrior-fury.p3"] = "5% more of the attack power Battle Shout gives per rank, to you and the group. It is also the fifteenth point Dual Wield Specialization needs before it opens.",
  ["warrior-fury.p4"] = "5% more damage from your off hand per rank. It is why you carry two weapons.",
  ["warrior-fury.p5"] = "After you are critically hit, your damage rises for a few swings.",
  ["warrior-fury.p6"] = "Opens the way to Bloodthirst. A big boost to your damage for a short time, and it also lowers your armour.",
  ["warrior-fury.p7"] = "Your attack speed rises for a few swings after a critical hit. Needs Enrage maxed.",
  ["warrior-fury.p8"] = "Hits with attack power and heals you a little.",
  ["warrior-fury.p9"] = "A cheaper Heroic Strike, which you will press all the time.",
  ["warrior-fury.s1"] = "One monster, levelling. The tree opens at 10 and its best buttons come later, so this stage is short.",
  ["warrior-fury.s1.r1"] = "Start every pull with it. It stuns and gives rage.",
  ["warrior-fury.s1.r2"] = "Spend spare rage here. It lands on your next swing.",
  ["warrior-fury.s1.r3"] = "A bleed that works while you hit.",
  ["warrior-fury.s1.r4"] = "At the start of a pull with your health full, because it pays rage for health.",
  ["warrior-fury.s2.opening"] = "Battle Shout, Charge, then hit. Berserker Stance comes at 30, and until you have Tactical Mastery a change of stance empties your rage, so change it when you have none to lose.",
  ["warrior-fury.s2.r1"] = "Before the pull, and renew it, because the bonus goes when it ends.",
  ["warrior-fury.s2.r2"] = "Spend everything else on this first.",
  ["warrior-fury.s2.r3"] = "Immune to fear while it lasts, and you gain rage from damage you take. Use it when fear is coming, or when you are being hit and want rage.",
  ["warrior-fury.s2.r4"] = "One hit on up to 4 enemies. Press it on a group.",
  ["warrior-fury.s2.r5"] = "20% more physical damage, and fear cannot touch you. It lowers your armour, so use it when the fight is short or you are not the target.",
  ["warrior-fury.s2.r6"] = "Spend what is left here, because rage kept is rage drained.",
  ["warrior-fury.s3.opening"] = "Battle Shout, Charge, then change to Berserker Stance, Death Wish, Bloodthirst. Tactical Mastery keeps some of your rage across the change.",
  ["warrior-fury.s3.r1"] = "On its cooldown. It is your main button and it heals a little.",
  ["warrior-fury.s3.r2"] = "Between Bloodthirsts, because it is damage while Bloodthirst waits.",
  ["warrior-fury.s3.r3"] = "Put everything else down, because it turns spare rage into damage.",
  ["warrior-fury.s3.r4"] = "Save it for a fight you will finish, because the armour it costs lasts as long as it does.",
  ["warrior-fury.s3.r5"] = "When you need rage or when fear is coming.",
  ["warrior-fury.s3.r6"] = "Spend what is left here, because rage kept is rage drained.",
  ["warrior-fury.split"] = "the filler before Dual Wield Specialization opens. This page takes Improved Battle Shout, because the group feels it. Booming Voice or Improved Cleave fill the same gap for a warrior who pulls alone.",
  ["warrior-protection.dry"] = "5 Sunders on the monster are 5 reasons for it to stay on you.",
  ["warrior-protection.intro"] = "Protection is the warrior who makes monsters hit you, and stays up while they do. Threat decides this job. Threat is the list a monster keeps of who to hit next. Protection starts at level 10, when Defensive Stance arrives.",
  ["warrior-protection.note"] = "(31 points in Protection for Shield Slam, then 20 in Arms and Fury).",
  ["warrior-protection.p1"] = "1% more block per rank, and sometimes a point of rage when you block.",
  ["warrior-protection.p10"] = "Cheaper Heroic Strike.",
  ["warrior-protection.p11"] = "1% more parry per rank. It also opens the row Tactical Mastery stands in, and a tank uses every point of parry.",
  ["warrior-protection.p12"] = "Keep rage when you move between stances.",
  ["warrior-protection.p13"] = "More critical hits, more threat.",
  ["warrior-protection.p14"] = "Rage from your swings.",
  ["warrior-protection.p2"] = "Defense skill. Fewer critical hits against you.",
  ["warrior-protection.p3"] = "2% more armour from your gear per rank.",
  ["warrior-protection.p4"] = "3% more threat per rank while in Defensive Stance. This is the tank's talent.",
  ["warrior-protection.p5"] = "Shield Block covers one more attack. Needs Shield Specialization maxed.",
  ["warrior-protection.p6"] = "A stun, and the door to Shield Slam.",
  ["warrior-protection.p7"] = "Revenge may stun.",
  ["warrior-protection.p8"] = "Sunder costs less, and you press it a lot.",
  ["warrior-protection.p9"] = "High damage, high threat, and it dispels a magic effect from the target half the time.",
  ["warrior-protection.s1"] = "A shield, a group, Defensive Stance.",
  ["warrior-protection.s1.opening"] = "Defensive Stance, Bloodrage, Sunder Armor, then Revenge when the game offers it.",
  ["warrior-protection.s1.r1"] = "The stance that adds threat. Stay in it while you tank.",
  ["warrior-protection.s1.r2"] = "Up to 5 times. Each stack lowers the monster's armour and adds a lot of threat.",
  ["warrior-protection.s1.r3"] = "It does nothing if the monster already hits you. Use it the moment a monster turns away.",
  ["warrior-protection.s1.r4"] = "Instant, with a lot of threat. Press it the moment it is lit.",
  ["warrior-protection.s1.r5"] = "More block for a short time. A block lights Revenge, so this also makes more of them.",
  ["warrior-protection.s1.r6"] = "Rage for health. At the start of a pull.",
  ["warrior-protection.s2"] = "Dungeons, groups of monsters.",
  ["warrior-protection.s2.opening"] = "Defensive Stance, Bloodrage, Sunder Armor, then Demoralizing Shout on a group.",
  ["warrior-protection.s2.r1"] = "Stack 5 on the monster you want held, because each stack lowers its armour and adds a lot of threat.",
  ["warrior-protection.s2.r2"] = "The best threat per rage you have.",
  ["warrior-protection.s2.r3"] = "Lowers the attack power of everything near you, so the healer takes less.",
  ["warrior-protection.s2.r4"] = "When the monster is hurting you and Revenge is not lit.",
  ["warrior-protection.s2.r5"] = "Every monster nearby turns to you. Use it when the group is losing the pull.",
  ["warrior-protection.s2.r6"] = "75% less damage from everything for a short time. Hold it for the worst moment.",
  ["warrior-protection.s2.r7"] = "Takes its weapon for a few seconds. Worth it on a monster that hits much harder than the rest.",
  ["warrior-protection.s3"] = "Dungeons and raids.",
  ["warrior-protection.s3.opening"] = "Defensive Stance, Sunder Armor, Shield Slam, Revenge when it is lit.",
  ["warrior-protection.s3.r1"] = "On its cooldown. High damage, and a lot of threat.",
  ["warrior-protection.s3.r2"] = "Instant, high threat.",
  ["warrior-protection.s3.r3"] = "Keep 5 stacks on, because each one adds threat and lowers the monster's armour.",
  ["warrior-protection.s3.r4"] = "Lower their attack power.",
  ["warrior-protection.s3.r5"] = "A stun, for the moment a monster must stop.",
  ["warrior-protection.s3.r6"] = "Hold it for the worst moment, because it takes 75% off the damage you take.",
